with cleaned as (select *, substring(firmware, 1, 4) as firmware_prefix, case when temp_c >= 34.6 then 'High' when temp_c >= 21.2 then 'Medium' else 'Low' end as temp_c_tier from device_readings where reading_ts >= timestamp '2025-09-01 08:00:00'), gaps as (select *, case when lag(reading_ts) over (partition by device_code order by reading_ts asc, id asc) is null or reading_ts > lag(reading_ts) over (partition by device_code order by reading_ts asc, id asc) + interval 20 minutes then 1 else 0 end as new_group_flag from cleaned), sessionized as (select id, device_code, reading_ts, humidity, pressure, sum(new_group_flag) over (partition by device_code order by reading_ts asc, id asc rows between unbounded preceding and current row) as island_id from gaps) select date_trunc('hour', reading_ts) as hour_window, count(distinct id) as distinct_ids, round(avg(island_id), 2) as avg_island_id, count(*) filter (where device_code = 'DV-04') as dv_04_rows, count(distinct device_code) as distinct_device_codes from sessionized group by date_trunc('hour', reading_ts) having distinct_ids > 1 order by hour_window asc nulls first;
